using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Controls.Primitives;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using RogControl;

public static class MousePerformanceGuiTests {
 static int checks;
 static readonly BindingFlags Hidden=BindingFlags.Instance|BindingFlags.NonPublic;
 static void Check(bool valid,string message){checks++;if(!valid)throw new Exception(message);}
 static Dictionary<string,object> Obj(params object[] pairs){var map=new Dictionary<string,object>();for(int i=0;i<pairs.Length;i+=2)map[(string)pairs[i]]=pairs[i+1];return map;}
 static object Field(MainWindow window,string name){return typeof(MainWindow).GetField(name,Hidden).GetValue(window);}
 static void Set(MainWindow window,string name,object value){typeof(MainWindow).GetField(name,Hidden).SetValue(window,value);}
 static object Invoke(MainWindow window,string name,params object[] values){return typeof(MainWindow).GetMethod(name,Hidden).Invoke(window,values);}
 static IEnumerable<DependencyObject> Walk(DependencyObject node){if(node==null)yield break;yield return node;for(int i=0;i<VisualTreeHelper.GetChildrenCount(node);i++)foreach(var child in Walk(VisualTreeHelper.GetChild(node,i)))yield return child;}
 static FrameworkElement Render(MainWindow window,int width,string name){Invoke(window,"ShowPage","device:mouse");var frame=(FrameworkElement)window.Content;frame.Measure(new Size(width,826));frame.Arrange(new Rect(0,0,width,826));frame.UpdateLayout();((ScrollViewer)Field(window,"pageScroll")).ScrollToTop();frame.UpdateLayout();var bitmap=new RenderTargetBitmap(width,826,96,96,PixelFormats.Pbgra32);bitmap.Render(frame);var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(bitmap));using(var output=File.Create(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"mouse-"+width+"-"+name+".png")))png.Save(output);return frame;}
 static Dictionary<string,object> MouseState(){return Obj("deviceId","synthetic-mouse","online",true,"readbackConfirmed",true,"setCapabilities",new[]{"dpiStage","activeDpiStage","pollingRate","angleSnapping","motionSync"},"snapshot",Obj("dpiStages",new[]{400,800,1600,3200},"dpiStagesY",new[]{400,700,1200,3200},"dpiColors",new object[]{new[]{255,0,0},new[]{180,0,255},new[]{0,0,255},new[]{0,255,0}},"activeDpiStage",2,"dpiStageCount",4,"pollingRate",1000,"buttonResponseMs",12,"angleSnapping",false,"motionSync",true,"angleTuning",0));}
 [STAThread] public static void Main(){
  var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};var window=new MainWindow(true);var states=(Dictionary<string,Dictionary<string,object>>)Field(window,"gearStates");var tabs=(Dictionary<string,string>)Field(window,"gearTabs");tabs["mouse"]="性能";var state=MouseState();states["mouse"]=state;
  foreach(int width in new[]{1180,1538,2560}){
   var frame=Render(window,width,"known-top");var nodes=Walk(frame).ToArray();var labels=nodes.OfType<TextBlock>().Select(t=>t.Text).ToArray();var dpiSliders=nodes.OfType<Slider>().Where(s=>s.Maximum==65000).ToArray();
   Check(dpiSliders.Length==2&&dpiSliders[0].Value==800&&dpiSliders[1].Value==700,"Separate X/Y readback survives layout "+width);Check(dpiSliders[0].IsEnabled&&!dpiSliders[1].IsEnabled,"Only verified paired-axis editing is enabled "+width);
   foreach(var slider in dpiSliders){var track=(Track)slider.Template.FindName("PART_Track",slider);Check(track!=null&&track.Thumb!=null&&track.DecreaseRepeatButton!=null&&track.IncreaseRepeatButton!=null,"Custom slider remains a functioning WPF track "+width);Check(slider.ActualWidth>=95,"DPI track stays reachable at "+width);}
   Check(nodes.OfType<Button>().Count(b=>Convert.ToString(b.Content)=="应用")==1,"There is one explicit apply action "+width);Check(nodes.OfType<Button>().Where(b=>Convert.ToString(b.Content)=="应用").All(b=>!b.IsEnabled),"Session-off render cannot apply "+width);
   Check(labels.Contains("在屏幕上显示 DPI 调整通知")&&labels.Contains("感应器性能配置")&&labels.Contains("角度偏移校准")&&labels.Contains("RF 智能检测"),"Original supported and unavailable sections keep their positions "+width);
   Check(!nodes.OfType<Image>().Any(),"Performance page does not insert a product-image column "+width);
   var pageScroll=(ScrollViewer)Field(window,"pageScroll");var pinned=(StackPanel)Field(window,"fixedPageHeader");Check(pinned.Children.Count==2,"Title and tab strip occupy pinned header "+width);var title=nodes.OfType<TextBlock>().First(t=>t.Text=="ROG HARPE II EXTREME EDITION 20");double top=title.TransformToAncestor(frame).Transform(new Point()).Y;pageScroll.ScrollToBottom();frame.UpdateLayout();Check(Math.Abs(title.TransformToAncestor(frame).Transform(new Point()).Y-top)<0.01,"Body scroll keeps device title pinned "+width);Check(pageScroll.VerticalOffset>0,"Long performance body can scroll at "+width);
   foreach(var label in Walk(pageScroll.Content as DependencyObject).OfType<TextBlock>().Where(t=>t.ActualWidth>0)){var point=label.TransformToAncestor(frame).Transform(new Point());Check(point.X>=248&&point.X+label.ActualWidth<=width-20,"Body text stays inside its horizontal viewport "+width+"/"+label.Text);}
   var bitmap=new RenderTargetBitmap(width,826,96,96,PixelFormats.Pbgra32);bitmap.Render(frame);var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(bitmap));using(var output=File.Create(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"mouse-"+width+"-known-bottom.png")))png.Save(output);
  }
  var tree=Walk(Render(window,1538,"draft")).ToArray();var x=tree.OfType<Slider>().First(s=>s.Maximum==65000);x.Value=900;var draft=(MousePerformanceDraft)Field(window,"mousePerformanceDraft");Check(draft.DpiX[1]==900&&draft.DpiY[1]==900&&draft.DirtyDpi[1],"DPI interaction changes only paired local draft");Check(((int[])((Dictionary<string,object>)state["snapshot"])["dpiStages"])[1]==800&&((int[])((Dictionary<string,object>)state["snapshot"])["dpiStagesY"])[1]==700,"Draft edit does not overwrite observed snapshot");Check(Field((WorkerClient)Field(window,"gearWorker"),"process")==null,"Rendering and editing never start a device worker");
  Set(window,"busy",true);x.Value=1000;Check(draft.DpiX[1]==900&&draft.DpiY[1]==900,"Stale slider events cannot alter a busy draft");var busyTree=Walk(Render(window,1180,"busy")).ToArray();Check(busyTree.OfType<Slider>().All(s=>!s.IsEnabled)&&busyTree.OfType<TextBox>().All(t=>!t.IsEnabled),"All performance editors are disabled while device request is busy");Set(window,"busy",false);
  Invoke(window,"RestoreMousePerformanceDraft",new MousePerformanceDraft{DeviceId="synthetic-mouse",DpiX=new int?[3]});Check(Field(window,"mousePerformanceDraft")==null,"Malformed restored arrays are rejected");Invoke(window,"RestoreMousePerformanceDraft",new MousePerformanceDraft{DeviceId="synthetic-mouse",DpiX=new int?[]{99,null,null,null}});Check(Field(window,"mousePerformanceDraft")==null,"Restored out-of-range DPI is rejected");Invoke(window,"RestoreMousePerformanceDraft",new MousePerformanceDraft{DeviceId="synthetic-mouse",DpiX=new int?[]{800,null,null,null},DpiY=new int?[]{700,null,null,null},DirtyDpi=new[]{true,false,false,false}});Check(Field(window,"mousePerformanceDraft")==null,"Unsupported dirty split-axis draft is rejected");
  states["mouse"]=Obj("deviceId","synthetic-mouse","online",false,"snapshot",((Dictionary<string,object>)state["snapshot"]));var offline=Walk(Render(window,1538,"offline")).ToArray();Check(offline.OfType<Slider>().All(s=>!s.IsEnabled)&&offline.OfType<TextBox>().All(t=>!t.IsEnabled),"Offline cached values cannot enable controls");Check(offline.OfType<TextBox>().Where(t=>t.Text=="800"||t.Text=="700").Count()==0,"Offline page does not present stale observed axis values");Check(((MousePerformanceDraft)Field(window,"mousePerformanceDraft")).SelectedStage==-1,"Unknown active DPI does not select a fictitious first stage");
  foreach(var slider in offline.OfType<Slider>().Where(s=>s.Maximum==65000)){var track=(Track)slider.Template.FindName("PART_Track",slider);Check(Walk(track.Thumb).OfType<Border>().All(b=>b.Background==null||b.Background.ToString()=="#00FFFFFF"||b.Background.ToString()=="#00000000"),"Unknown DPI has no visible current-value thumb");Check(Walk(track.DecreaseRepeatButton).OfType<Border>().All(b=>b.Background==null||b.Background.ToString()!="#FFD7BF6C"),"Unknown DPI has no gold current-value filled segment");}
  var missingY=MouseState();((Dictionary<string,object>)missingY["snapshot"]).Remove("dpiStagesY");states["mouse"]=missingY;Set(window,"mousePerformanceDraft",null);var paired=Walk(Render(window,1538,"paired-draft")).OfType<Slider>().Where(s=>s.Maximum==65000).ToArray();Check(paired[0].IsEnabled&&paired[1].Tag is bool&&!(bool)paired[1].Tag,"Verified X can edit paired draft without fabricating an unread Y");paired[0].Value=901;var editedTrack=(Track)paired[1].Template.FindName("PART_Track",paired[1]);paired[1].ApplyTemplate();paired[1].UpdateLayout();editedTrack=(Track)paired[1].Template.FindName("PART_Track",paired[1]);Check((bool)paired[1].Tag&&paired[1].Value==901&&Walk(editedTrack.Thumb).OfType<Border>().Any(b=>b.Background!=null&&b.Background.ToString()=="#FFD7BF6C"),"Explicit paired draft edit restores the Y draft marker");
  var planDraft=new MousePerformanceDraft{DeviceId="synthetic-mouse",PollingRate=8000,MotionSync=false,DirtyMotion=true,DirtyPolling=true};var plan=Commands(planDraft,4);Check(plan.Select(c=>c.Key).SequenceEqual(new[]{"motionSync","pollingRate"}),"Disabling sync precedes requesting 8000 Hz");planDraft.PollingRate=1000;planDraft.MotionSync=true;plan=Commands(planDraft,4);Check(plan.Select(c=>c.Key).SequenceEqual(new[]{"pollingRate","motionSync"}),"Lower rate is applied before enabling sync");planDraft.PollingRate=8000;Reject(()=>Commands(planDraft,4),"Incompatible dirty pair is rejected before commands");planDraft.MotionSync=null;planDraft.DirtyMotion=false;Reject(()=>Commands(planDraft,4),"8000 Hz does not assume an unread sync state");planDraft.PollingRate=1000;planDraft.DirtyPolling=false;planDraft.DirtyStage=true;planDraft.SelectedStage=3;planDraft.DpiX[0]=500;planDraft.DpiY[0]=500;planDraft.DirtyDpi[0]=true;Reject(()=>Commands(planDraft,2),"Inactive final stage rejects the entire plan before earlier DPI writes");planDraft.DirtyStage=false;plan=Commands(planDraft,4);Check(plan.Count==1&&plan[0].Key=="dpiStage","Only edited stage appears in the plan");planDraft.DpiX[0]=900;Check(Convert.ToInt32(((Dictionary<string,object>)plan[0].Value)["dpi"],CultureInfo.InvariantCulture)==500,"Plan scalars remain detached from later draft changes");
  var profileState=Obj("online",true,"snapshot",Obj("profileInformationUnconfirmed",false,"profileCount",4,"activeProfile",1));Check((string)Invoke(window,"OriginalGearProfileName",profileState,"mouse")=="配置文件 1","Confirmed mouse profile is shown");((Dictionary<string,object>)profileState["snapshot"])["profileInformationUnconfirmed"]=true;Check((string)Invoke(window,"OriginalGearProfileName",profileState,"mouse")=="配置文件 —","Unconfirmed raw profile never becomes a current value");((Dictionary<string,object>)profileState["snapshot"])["profileInformationUnconfirmed"]=false;((Dictionary<string,object>)profileState["snapshot"])["activeProfile"]=5;Check((string)Invoke(window,"OriginalGearProfileName",profileState,"mouse")=="配置文件 —","Profile outside returned count is unknown");((Dictionary<string,object>)profileState["snapshot"])["profileCount"]=0;Check((string)Invoke(window,"OriginalGearProfileName",profileState,"mouse")=="配置文件 —","Zero profile count is not a current configuration");
  Check(Field((WorkerClient)Field(window,"gearWorker"),"process")==null,"All GUI checks completed without a worker or native write");Console.WriteLine("Mouse performance GUI: "+checks+" checks passed. Synthetic data and hidden rendering only; no device writes.");app.Shutdown();
 }
 static object Field(WorkerClient worker,string name){return typeof(WorkerClient).GetField(name,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(worker);}
 static List<KeyValuePair<string,object>> Commands(MousePerformanceDraft draft,int? count){return (List<KeyValuePair<string,object>>)typeof(MainWindow).GetMethod("MousePerformanceCommands",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{draft,count});}
 static void Reject(Action action,string message){bool rejected=false;try{action();}catch(TargetInvocationException error){rejected=error.InnerException is ArgumentException;}Check(rejected,message);}
}
